<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import type {LabRun,LabRow,LabReview} from '../algorithmLab';
import {post} from '../api';
import {money,date} from '../format';
const props=defineProps<{run:LabRun;compact?:boolean}>();
defineEmits<{open:[string];monitor:[string]}>();
const expanded=ref(''),onlyMatched=ref(false),review=ref<LabReview>(),reviewing=ref(false),error=ref(''),limit=ref(50);
const rows=computed(()=>onlyMatched.value?props.run.rows.filter(r=>r.matched):props.run.rows);
watch(()=>props.run.id,()=>{expanded.value='';review.value=undefined;error.value='';limit.value=50;});
watch(onlyMatched,()=>{limit.value=50;});
async function analyze(row:LabRow,decision=false){reviewing.value=true;error.value='';review.value=undefined;try{review.value=(await post<LabReview>(decision?'/lab/decision':'/lab/review',{run_id:props.run.id,security_id:row.security.id})).data;}catch(e){error.value=String(e);}finally{reviewing.value=false;}}
</script>
<template><div class="lab-result-summary"><strong>计算 {{run.total}} 只 · 满足 {{run.matched}} 只 · 数据不足 {{run.skipped}} 只</strong><span class="tiny muted">{{date(run.finished_at)}}</span><label v-if="!compact"><input type="checkbox" v-model="onlyMatched"> 仅看符合条件</label></div><div class="lab-results" v-if="rows.length"><article v-for="row in rows.slice(0,limit)" :key="row.security.id" class="lab-result" :class="{expanded:expanded===row.security.id||compact}"><div class="lab-result-line"><button class="stock-link" @click="$emit('open',row.security.id)"><strong>{{row.security.name}}</strong><span class="tiny muted">{{row.security.code}}</span></button><strong>{{money(row.price)}}</strong><span class="badge" :class="row.matched?'blue':''">{{row.action}}</span><span class="lab-hit">命中 {{row.hit_count}} / {{row.total}}</span><span class="tiny muted">数据 {{row.data_as_of??'缺失'}}</span><button v-if="!compact" class="text-button" @click="expanded=expanded===row.security.id?'':row.security.id;review=undefined">{{expanded===row.security.id?'收起':'查看依据'}}</button></div><div v-if="expanded===row.security.id||compact" class="lab-evidence"><p class="tiny" :class="row.data_status==='STALE'?'error-line':'muted'">{{row.data_note}} · 计算口径：未复权原价</p><div v-for="r in row.results" :key="r.id" class="lab-evidence-row"><span :class="r.status==='MISSING'?'muted':r.matched?'lab-positive':''">{{r.status==='MISSING'?'数据不足':r.matched?'条件满足':'条件未满足'}}</span><strong>{{r.name}}</strong><span>{{r.reason}}</span></div><div class="lab-evidence-actions"><button class="button small" @click="$emit('monitor',row.security.id)">加入算法监测</button><button class="button small" @click="analyze(row,true)" :disabled="reviewing">Jev 决策分流</button><button class="button small" @click="analyze(row)" :disabled="reviewing">{{reviewing?'Agent 分析中…':'Agent 复核'}}</button><span class="tiny muted">需配置模型 · 点击可能产生模型费用</span></div><p class="error-line" v-if="error">{{error}}</p><div v-if="review" class="lab-review"><strong>{{review.status==='SUCCEEDED'?'Agent 分析':review.status==='UNAVAILABLE'?'模型待配置':'分析未完成'}}</strong><p>{{review.summary}}</p></div></div></article><p v-if="rows.length>limit" class="muted tiny"><button class="button small" @click="limit+=100">继续展示（已展示 {{limit}} / {{rows.length}}）</button></p></div><div v-else class="lab-empty">没有满足条件的股票。取消“仅看符合条件”可查看全部依据。</div></template>
